const ATELIER_VARIANTS: Record<BlockType, readonly string[]> = (() => {
  const variants = {} as Record<BlockType, readonly string[]>;
  for (const type of BLOCK_TYPES) variants[type] = NEUTRAL_BLOCK_TYPES.includes(type) ? ["neutral"] : ["atelier"];
  return variants;
})();

